@reference "../styles.css";

/* The block root is the inset main region (padding is allowed only on the root). */
.app {
  @apply flex min-w-0 flex-col gap-4 p-4 md:p-6;
}

.app__skip {
  @apply sr-only;
}

.app__skip:focus-visible {
  @apply not-sr-only absolute start-4 top-4 z-50;
}

.app__brand {
  @apply flex items-center gap-2;
