export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideRouter(routes),
    // Keeps CDK overlays (the mobile sidebar sheet, tooltips) above position:fixed chrome.
    provideSpartanHlm(),
  ]
};

